# Auto-generated static frontend bundle for Railway deployment (when Node/npm is not installed in the Python image)
import base64

EMBEDDED_FRONTEND = {
    '/assets/index-DanYcRer.js': '',
    '/assets/index-OSpWtc4Z.css': '',
    '/index.html': '',
}

BUNDLE_FILES = EMBEDDED_FRONTEND

def get_embedded_asset(path: str):
    clean_p = "/index.html" if path in ("", "/") else path
    b64 = EMBEDDED_FRONTEND.get(clean_p)
    if not b64 and clean_p.startswith("/assets/"):
        ext = ".js" if clean_p.endswith(".js") else (".css" if clean_p.endswith(".css") else "")
        if ext:
            for k, v in EMBEDDED_FRONTEND.items():
                if k.startswith("/assets/") and k.endswith(ext):
                    clean_p = k
                    b64 = v
                    break
    if not b64 and not clean_p.startswith("/assets/"):
        clean_p = "/index.html"
        b64 = EMBEDDED_FRONTEND.get("/index.html")
    if not b64:
        return None
    mime_type = "text/html; charset=utf-8"
    if clean_p.endswith(".js") or clean_p.endswith(".mjs"):
        mime_type = "application/javascript; charset=utf-8"
    elif clean_p.endswith(".css"):
        mime_type = "text/css; charset=utf-8"
    elif clean_p.endswith(".svg"):
        mime_type = "image/svg+xml"
    return (base64.b64decode(b64), mime_type)

def get_bundled_asset(path: str):
    res = get_embedded_asset(path)
    return res[0] if res else None
